class SharedAuthManager(private val scope: CoroutineScope) {
    private val defaultVault = File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS), "ObsidianVault/.auth/chatgpt_session.json")
    private val _session = MutableStateFlow<SharedAuthSession?>(null)
    val session: StateFlow<SharedAuthSession?> = _session.asStateFlow()
    init { loadOrRefreshSession(); startWatcher() }
    fun loadOrRefreshSession() {
        if (!defaultVault.exists()) return
        val json = JSONObject(defaultVault.readText())
        val s = SharedAuthSession(json.optString("accessToken"), json.optString("refreshToken"), json.optString("clientId"), json.optLong("expiresAt"))
        if (s.isValid) _session.value = s
        else if (s.refreshToken.isNotBlank()) scope.launch(Dispatchers.IO) { refreshAccessToken(s.refreshToken) }
    }
    private fun startWatcher() {
        val observer = object : FileObserver(defaultVault.parentFile!!.absolutePath, MODIFY or CREATE) {
            override fun onEvent(event: Int, path: String?) { if (path == "chatgpt_session.json") loadOrRefreshSession() }
        }
        observer.startWatching()
    }
}
